(async () => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  try {
    const tab = Array.from(document.querySelectorAll('button')).find(b => (b.innerText||'').trim().toLowerCase().includes('client id'));
    if (tab) tab.click();
    await sleep(1200);
    const ci = document.getElementById('fy_client_id');
    if (ci) {
      const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
      setter.call(ci, 'YA38754');
      ci.dispatchEvent(new Event('input', {bubbles:true}));
      ci.dispatchEvent(new Event('change', {bubbles:true}));
    }
    await sleep(400);
    const cont = Array.from(document.querySelectorAll('button')).find(b => (b.innerText||'').trim() === 'Continue');
    if (cont) cont.click();
    await sleep(7000);
  } catch(e) { /* ignore */ }
  const boxes = Array.from(document.querySelectorAll('input[type=number]')).map(i => i.id);
  const vis = (id) => { const el = document.getElementById(id); return el && el.offsetParent !== null; };
  return JSON.stringify({
    url: location.href,
    error: (Array.from(document.querySelectorAll('div,span,p,label')).map(e=>(e.innerText||'').trim()).filter(t=>/invalid|incorrect|error|wrong|expired|resend|otp|pin/i.test(t) && t.length<80).slice(0,6)),
    otpBoxesVisible: vis('first') && vis('sixth'),
    pwVisible: vis('password'),
    buttons: Array.from(document.querySelectorAll('button')).map(b=>(b.innerText||'').trim()).filter(Boolean).filter(t=>/otp|pin|login|verify|send|resend|cancel/i.test(t)).slice(0,8),
    inputsVisible: Array.from(document.querySelectorAll('input')).filter(i=>i.offsetParent!==null).map(i=>i.id+':'+i.type).slice(0,10)
  });
})()
